const svgI=k=>IC[k]?`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${IC[k]}"/></svg>`:`<span class="nd" aria-hidden="true"></span>`;
document.getElementById("skl").innerHTML=SK.map(([k,v],i)=>`<div class="sg rv"><h3><small>${String(i+1).padStart(2,"0")}</small>${k}</h3><ul>${v.split(/, (?![^(]*\))/).map(t=>`<li>${svgI(t)}${t}</li>`).join("")}</ul></div>`).join("");
const LM=Object.keys(IC),half=Math.ceil(LM.length/2),rowH=a=>{const h=a.map(k=>`<span class="lg">${svgI(k)}${k.replace(" (Lambda, S3, Athena)","")}</span>`).join("");return h+h};
document.getElementById("lm").innerHTML=`<div class="row">${rowH(LM.slice(0,half))}</div><div class="row rev">${rowH(LM.slice(half))}</div>`;
// recognition

// rotating word
const words=["agentic","intelligent","private","reliable"];let wi=0;const rot=document.getElementById("rot");
(async()=>{if(reduce)return;const w=ms=>new Promise(r=>setTimeout(r,ms));while(true){await w(2600);const a=words[wi];for(let i=a.length;i>=0;i--){rot.textContent=a.slice(0,i);await w(38)}wi=(wi+1)%words.length;const b=words[wi];for(let i=1;i<=b.length;i++){rot.textContent=b.slice(0,i);await w(75)}}})();

// count-up
if(!reduce)document.querySelectorAll("[data-n]").forEach(b=>{const n=+b.dataset.n,sup=b.querySelector("sup");const t0=performance.now()+400;const f=t=>{const k=Math.max(0,Math.min(1,(t-t0)/1500)),e=1-Math.pow(1-k,3);b.firstChild.nodeValue=Math.round(n*e);if(k<1)requestAnimationFrame(f)};b.firstChild.nodeValue="0";requestAnimationFrame(f)});

// reveal (items below the fold lift in; everything stays readable)
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.remove("pre");io.unobserve(e.target)}}),{threshold:.1});
if(!reduce)document.querySelectorAll(".rv").forEach((el,i)=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add("pre");el.style.transitionDelay=(i%4)*.06+"s";io.observe(el)}});

// portrait tilt
const tilt=document.getElementById("tilt");
tilt.addEventListener("pointermove",e=>{if(reduce)return;const r=tilt.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;tilt.style.transform=`perspective(1000px) rotateY(${x*12}deg) rotateX(${-y*12}deg)`});
tilt.addEventListener("pointerleave",()=>tilt.style.transform="");
// cursor glow
const cg=document.getElementById("cglow");addEventListener("pointermove",e=>{if(reduce||e.pointerType!=="mouse")return;cg.style.left=e.clientX+"px";cg.style.top=e.clientY+"px"},{passive:true});

// nav scrollspy, sliding pill, progress, timeline fill
const links=[...document.querySelectorAll("#navl a")],pip=document.getElementById("pip"),prog=document.getElementById("prog");
function placePip(a){if(!a){pip.style.width="0";return}const ul=a.parentElement.parentElement.getBoundingClientRect(),r=a.getBoundingClientRect();const box=a.parentElement.parentElement;pip.style.left=r.left-ul.left+box.scrollLeft+"px";pip.style.width=r.width+"px";if(box.scrollWidth>box.clientWidth){const t=a.offsetLeft-(box.clientWidth-a.offsetWidth)/2;box.scrollTo({left:t,behavior:"smooth"})}}
function onScroll(){const max=document.documentElement.scrollHeight-innerHeight;prog.style.setProperty("--p",(scrollY/max*100).toFixed(2)+"%");
 let cur=null;links.forEach(a=>{const s=document.getElementById(a.dataset.s);if(s.getBoundingClientRect().top<innerHeight*.45)cur=a});
 links.forEach(a=>a.classList.toggle("on",a===cur));placePip(cur);
 }
addEventListener("scroll",onScroll,{passive:true});addEventListener("resize",onScroll);onScroll();

// aurora canvas
const av=document.getElementById("aurora"),ax=av.getContext("2d");let at=0;
const blobs=[{x:.72,y:.25,r:.42,c:[92,200,214],a:.22,s:.7},{x:.3,y:.1,r:.36,c:[45,212,191],a:.12,s:1.1},{x:.9,y:.6,r:.3,c:[120,140,230],a:.10,s:.9}];
function aur(){const w=av.clientWidth,h=av.clientHeight,d=Math.min(devicePixelRatio||1,2);if(av.width!==Math.round(w*d)){av.width=Math.round(w*d);av.height=Math.round(h*d)}
 ax.setTransform(d,0,0,d,0,0);ax.clearRect(0,0,w,h);ax.globalCompositeOperation="lighter";
 blobs.forEach((b,i)=>{const x=(b.x+Math.sin(at*b.s+i)*.06)*w,y=(b.y+Math.cos(at*b.s*.8+i*2)*.08)*h,r=b.r*Math.max(w,h);const g=ax.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,`rgba(${b.c},${b.a})`);g.addColorStop(1,`rgba(${b.c},0)`);ax.fillStyle=g;ax.fillRect(0,0,w,h)});
 ax.globalCompositeOperation="source-over";ax.fillStyle="rgba(92,200,214,.35)";
 for(let i=0;i<60;i++){const px=((i*97.3+at*12*(1+i%3))%w+w)%w,py=(i*53.7%h)+Math.sin(at+i)*6;ax.globalAlpha=.25+.25*Math.sin(at*2+i);ax.fillRect(px,py,1.4,1.4)}ax.globalAlpha=1;
 if(!reduce)at+=.004;requestAnimationFrame(aur)}
aur();

