// lab: fill stage bars and result ranges when the section comes into view
(()=>{const run=root=>{root.querySelectorAll(".stages").forEach(st=>{st.querySelectorAll(".stg").forEach((g,i)=>{const f=g.classList.contains("done")?1:g.classList.contains("now")?.55:0;setTimeout(()=>g.querySelector("i").style.setProperty("--f",f),i*180)})});
  root.querySelectorAll(".seg").forEach((s,i)=>setTimeout(()=>s.style.width=s.dataset.w,300+i*400))};
 const lab=document.getElementById("lab");
 if(matchMedia("(prefers-reduced-motion: reduce)").matches){run(lab);return}
 let done=false;const go=()=>{if(!done){done=true;run(lab)}};const o=new IntersectionObserver(es=>{if(es[0].isIntersecting){go();o.disconnect()}},{threshold:.2});o.observe(lab);setTimeout(go,3500)})();

// agent graph animation for the featured card
(()=>{const c=document.getElementById("agent");if(!c)return;const x=c.getContext("2d");let t=0;
 const N=[["user",.06,.5],["planner",.3,.5],["retriever",.55,.18],["sql_tool",.55,.5],["web_tool",.55,.82],["critic",.78,.5],["answer",.95,.5]];
 const E=[[0,1],[1,2],[1,3],[1,4],[2,5],[3,5],[4,5],[5,6],[5,1]];
 function f(){const w=c.clientWidth,h=c.clientHeight,d=Math.min(devicePixelRatio||1,2);if(!w){requestAnimationFrame(f);return}if(c.width!==Math.round(w*d)){c.width=Math.round(w*d);c.height=Math.round(h*d)}
  x.setTransform(d,0,0,d,0,0);x.clearRect(0,0,w,h);const P=N.map(n=>[n[1]*(w-40)+20,n[2]*(h-30)+15]);
  E.forEach(([a,b],i)=>{x.strokeStyle="rgba(92,200,214,.22)";x.lineWidth=1;x.beginPath();if(i===8){x.moveTo(...P[a]);x.quadraticCurveTo((P[a][0]+P[b][0])/2,h-2,...P[b])}else{x.moveTo(...P[a]);x.lineTo(...P[b])}x.stroke();
   const k=((t*.6+i*.37)%1);let px,py;if(i===8){const mx=(P[a][0]+P[b][0])/2,my=h-2;px=(1-k)*(1-k)*P[a][0]+2*(1-k)*k*mx+k*k*P[b][0];py=(1-k)*(1-k)*P[a][1]+2*(1-k)*k*my+k*k*P[b][1]}else{px=P[a][0]+(P[b][0]-P[a][0])*k;py=P[a][1]+(P[b][1]-P[a][1])*k}
   x.fillStyle=i===8?"#E8C27A":"#A5F0F7";x.beginPath();x.arc(px,py,2.2,0,7);x.fill()});
  N.forEach((n,i)=>{const [px,py]=P[i];const g=.5+.5*Math.sin(t*3+i);x.fillStyle="#0F131A";x.strokeStyle=`rgba(92,200,214,${.45+.4*g})`;x.lineWidth=1.2;x.beginPath();x.arc(px,py,6,0,7);x.fill();x.stroke();
   x.fillStyle="rgba(236,232,225,.55)";x.font="500 10px 'JetBrains Mono',monospace";x.textAlign="center";x.fillText(n[0],px,py+(n[2]<.3?-12:18))});
  if(!matchMedia("(prefers-reduced-motion: reduce)").matches)t+=.008;requestAnimationFrame(f)}
 f()})();

